import 'package:flutter/material.dart';
import '../data/app_database.dart';
import 'home_screen.dart';
class SummaryScreen extends StatefulWidget{final int dayNumber,correct,total;const SummaryScreen({super.key,required this.dayNumber,required this.correct,required this.total});@override State<SummaryScreen>createState()=>_SummaryScreenState();}
class _SummaryScreenState extends State<SummaryScreen>{bool saved=false;@override void initState(){super.initState();_save();}Future<void>_save()async{final double score = widget.total == 0 ? 0.0 : widget.correct / widget.total * 100.0;await AppDatabase.instance.completeDay(widget.dayNumber,score,widget.correct);if(mounted)setState(()=>saved=true);} @override Widget build(BuildContext c){final double pct = widget.total == 0 ? 0.0 : widget.correct / widget.total * 100.0;return Scaffold(body:Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Text('🎉',style:TextStyle(fontSize:64)),const SizedBox(height:18),const Text('Session Complete!',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:10),Text('${widget.correct}/${widget.total} Correct | ${pct.toStringAsFixed(0)}% Accuracy',style:const TextStyle(fontSize:18)),const SizedBox(height:14),Text('🔥 Day ${widget.dayNumber} complete',style:const TextStyle(fontWeight:FontWeight.w700)),const SizedBox(height:28),SizedBox(width:double.infinity,child:FilledButton(onPressed:saved?()=>Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>const HomeScreen()),(_)=>false):null,child:Text(widget.dayNumber<30?'अगला दिन':'वापस जाएँ')))]))));}}
